import { and, eq, sql } from 'drizzle-orm';
import type { Database } from '../auth.ts';
import { characters } from '../db/schema.ts';
import { inLiveUniverse } from '../universe-scope.ts';
import { completeDetailed, ReplyCutOffError, type GatewayDeps } from './gateway.ts';
import { arcIsCurrent, arcRequest } from './arc-request.ts';
import { jobSpendMeter } from './job-spend.ts';

// Character arc summaries: what happens to a character across the universe's
// stories, cached on the character and regenerated by the background job,
// never on view. Generated metadata in its own column, like scene summaries:
// written directly, and it never touches the writer's own summary or notes.
// An arc is stored with the fingerprint of the request it was written from
// (arc_summary_input) and is out of date when the request that would be sent
// now differs (see arc-request.ts). No save marks it: arc_summary_at is only
// the time it was written.

const MAX_ARC_TOKENS = 400;

export type ArcResult = {
	// written: a new arc is stored; empty: the character appears in no scene, so
	// nothing was asked; missing: not the user's character; capped: earlier
	// attempts of this job already spent the ceiling (spentUsd), so nothing was
	// asked.
	outcome: 'written' | 'empty' | 'missing' | 'capped';
	spentUsd?: number;
};

// Write (or rewrite) one character's arc. Owner scoped. Throws when the
// Assistant call fails, leaving any earlier arc in place. An arc that is
// current is rewritten too: the job only runs when the writer asks, and then
// they want another take.
export async function summariseCharacterArc(
	db: Database,
	opts: { userId: string; characterId: string; jobId?: string; signal?: AbortSignal },
	deps: GatewayDeps = {}
): Promise<ArcResult> {
	const { userId, characterId, signal } = opts;
	const [character] = await db
		.select({ id: characters.id, name: characters.name, universeId: characters.universeId })
		.from(characters)
		.where(
			and(
				eq(characters.id, characterId),
				eq(characters.ownerId, userId),
				inLiveUniverse(characters.universeId)
			)
		);
	if (!character) return { outcome: 'missing' };

	const request = await arcRequest(db, character);
	if (!request) {
		// Nothing left to retell (scenes deleted, or only in muted stories), so an
		// earlier arc goes too.
		await db
			.update(characters)
			.set({
				arcSummaryMd: null,
				arcSummaryAt: null,
				arcSummaryInput: null,
				updatedAt: sql`${characters.updatedAt}`
			})
			.where(eq(characters.id, character.id));
		return { outcome: 'empty' };
	}

	// One request, but a job pg-boss retries sends it again: the meter carries
	// what earlier attempts spent, and the arc counts towards the ceiling like
	// any other background run.
	const meter = await jobSpendMeter(db, { userId, jobId: opts.jobId });
	if (meter.capReached) return { outcome: 'capped', spentUsd: meter.spentUsd };
	let result: Awaited<ReturnType<typeof completeDetailed>>;
	try {
		result = await completeDetailed(
			db,
			{
				userId,
				// An arc reads across the universe, so it runs on its models.
				universeId: character.universeId,
				role: 'utility',
				enableTools: false,
				messages: request.messages,
				maxTokens: MAX_ARC_TOKENS,
				meter,
				signal
			},
			deps
		);
	} finally {
		await meter.flush();
	}
	if (result.cutOff) {
		throw new ReplyCutOffError(
			'The arc was cut off at the reply limit. Raise Longest reply for Background work in its Tune window under Account, Assistant.'
		);
	}
	const text = result.content.trim();
	if (!text) throw new Error('The Assistant returned an empty arc.');

	// Stored with the fingerprint of the request that was sent, not of the
	// scenes as they are now: anything that changed while the model was writing
	// (an edit, a deleted scene, a story muted) leaves the fingerprint behind,
	// so the arc reads as out of date and is kept out of the context.
	await db
		.update(characters)
		.set({
			arcSummaryMd: text,
			arcSummaryInput: request.input,
			arcSummaryAt: sql`now()`,
			updatedAt: sql`${characters.updatedAt}`
		})
		.where(eq(characters.id, character.id));
	return { outcome: 'written' };
}

// The arc for a Plan page's selected entity: its stored text and whether it is
// out of date, for a character; null for anything else.
export async function planArc(
	db: Database,
	resolved: {
		kind: string;
		entity: {
			id: string;
			name: string;
			universeId: string;
			arcSummaryMd?: string | null;
			arcSummaryInput?: string | null;
		};
	} | null
): Promise<{ summaryMd: string | null; stale: boolean } | null> {
	if (resolved?.kind !== 'character') return null;
	const { entity } = resolved;
	const stored = {
		arcSummaryMd: entity.arcSummaryMd ?? null,
		arcSummaryInput: entity.arcSummaryInput ?? null
	};
	// An arc never written has nothing to be out of date.
	if (!stored.arcSummaryMd) return { summaryMd: null, stale: false };
	return {
		summaryMd: stored.arcSummaryMd,
		stale: !arcIsCurrent(stored, await arcRequest(db, entity))
	};
}
